SELECT name, setting
FROM pg_settings
WHERE name IN ('wal_level', 'full_page_writes', 'wal_compression', 'synchronous_commit', 'checkpoint_timeout');

-- Where is the current WAL position?
SELECT pg_current_wal_lsn();

-- How much WAL has been generated since the last checkpoint?
SELECT pg_current_wal_lsn() - pg_control_checkpoint();
